// === Tab: mySketch ===
let points = [];

function setup() {
	createCanvas(1024, 800);
	angleMode(DEGREES);

	for (let r = height / 2 * 0.85; r > 0; r -= height / 2 / 20) {
		let angleStep = map(r, height / 2 * 0.85, 0, .1, 10);
		let startAngle = random(360);
		for (let angle = startAngle; angle < startAngle + 360; angle += angleStep) {
			let x = width + cos(angle) * r;
			let y = height + sin(angle) * r;
			points.push(new Mover(x, y));
		}
	}
	background(0, 47, 64);
}

function draw() {
	for (let p of points) {
		p.update();
		p.display();
	}
}

class Mover {
	constructor(_x, _y, _nx = 50, _ny = 50) {
		this.pos = createVector(_x, _y);
		let nx = 1 / 100;
		let ny = 1 / 50;
		let nz = 1 / 50;
		this.noiseScale = createVector(nx, ny, nz);
		this.life = 100;
		this.lifeRatio = this.life / 500;
	}
	update() {
		let n = noise(this.pos.x * this.noiseScale.x, this.pos.y * this.noiseScale.y);
		let angle = map(-n, 0, 1, -90, 90);

		angle = (angle + frameCount / 10) % 360;
		let vel = createVector(2 * sin(angle), 2 * cos(angle));

		this.pos.add(vel);
		this.life -= this.lifeRatio;
	}
	display() {
		stroke(255,237,237, this.life / 2);
		// stroke(this.life / 2, 100, 80, this.life / 2);
		point(this.pos.x, this.pos.y);
	}
}

